const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='codepath-learning-v1';let state={version:1,current:'pc-01',done:{},drafts:{},notes:{},checks:{},projectChecks:{},viewedSolutions:{},projectEvidence:{},gameProgress:{},miniDone:{},wrongBook:[]};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1)state=LearningCore.normalize(saved,LESSONS,PROJECTS)}catch(e){}state=LearningCore.normalize(state,LESSONS,PROJECTS);let worker=null,job=null,timeout=null,route='',toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-state').textContent='本机自动保存'}catch(e){$('#save-state').textContent='保存失败，请备份';toast('浏览器存储不可用，请及时备份学习进度。')}updateSide()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function updateSide(){const count=LESSONS.filter(l=>state.done[l.id]).length;$('#side-progress').style.width=(count/LESSONS.length*100)+'%';$('#side-count').textContent=`已完成 ${count} / ${LESSONS.length} 个小节`}
function go(hash){if(location.hash===hash)render();else location.hash=hash}
function getLesson(){return LESSONS.find(l=>l.id===state.current)||LESSONS[0]}
function render(){stopExtra();if(job)stopRun(false);const [view,arg]=location.hash.slice(1).split('/');route=view||'home';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(route==='course'?'path':route==='game'?'games':route==='project'?'projects':route)));if(route==='home')renderHome();else if(route==='daily')renderDaily();else if(route==='games')renderGames();else if(route==='game')renderGame(arg);else if(route==='audit')renderAudit();else if(route==='learn'){if(arg&&LESSONS.some(l=>l.id===arg)){state.current=arg;save()}if(!trackUnlocked(getLesson().track)){renderLockedTrack(getLesson().track)}else{renderLesson();addLessonOrientation();addBeginnerPanels();addMasteryPanel()}}else if(route==='path')renderPath();else if(route==='course')renderCourse(arg);else if(route==='projects')renderProjects();else if(route==='project')renderProject(arg);else if(route==='notes')renderNotes();else if(route==='progress')renderProgress();else{go('#learn');return}updateSide();window.scrollTo({top:0,behavior:'instant'})}
function renderLockedTrack(trackId){const t=TRACKS.find(x=>x.id===trackId),g=trackGate(trackId);crumb(t.name);$('#main').innerHTML=`<a class="back-link" href="#path">← 返回学习路径</a><section class="locked-stage"><div class="game-icon">🔒</div><span class="eyebrow">先补一块地基</span><h1>${esc(t.name)} 还没有解锁</h1><p>先完成“${esc(g.title)}”。它会检查前一阶段最小知识，不会写代码也能做；答错会立刻讲原因。</p><a class="primary" href="#game/${g.id}">去闯关解锁 →</a></section>`}
function crumb(name){$('#breadcrumb').innerHTML=`我的学习 <span>/</span> ${esc(name)}`}
function renderLesson(){const l=getLesson(),track=TRACKS.find(t=>t.id===l.track),lessons=LESSONS.filter(x=>x.track===l.track),idx=lessons.indexOf(l),guided=l.kind==='guided';crumb(track.name);$('#main').innerHTML=`<div class="lesson-top"><div><span class="eyebrow">LEARN BY DOING · 边学边练</span><h1>${esc(track.name)}</h1><p>不必一次学会所有。完成眼前这一步，就很好。</p></div><select id="lesson-select" class="course-switch" aria-label="选择当前课程的小节">${lessons.map((x,i)=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${state.done[x.id]?'✓ ':''}${String(i+1).padStart(2,'0')} · ${esc(x.title)}</option>`).join('')}</select></div><div class="lesson-progress" aria-label="课程进度">${lessons.map(x=>`<a href="#learn/${x.id}" title="${esc(x.title)}" aria-label="${esc(x.title)}" class="${x.id===l.id?'current':state.done[x.id]?'done':''}"></a>`).join('')}</div><div class="workspace"><section class="lesson-panel"><div class="panel-tabs"><span>学习与任务</span><span class="tab-meta">约 ${l.minutes} 分钟 · ${idx+1} / ${lessons.length}</span></div><article class="lesson-body"><span class="lesson-num">LESSON ${String(idx+1).padStart(2,'0')} / ${guided?(l.localLab?'本机实验':'概念动手'):'交互练习'}</span><h2>${esc(l.title)}</h2><p>${l.intro}</p><h3>先理解一个小知识</h3><p>${l.concept}</p>${l.analogy?`<div class="analogy">${l.analogy}</div>`:''}<pre><code>${esc(l.example)}</code></pre><p>${l.explain}</p><div class="task-box"><div class="task-heading"><span>✓</span>轮到你动手了</div><ol class="steps">${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div><div class="reflection"><b>再想一步</b><br>${l.reflection}</div><a class="source" href="${l.source||track.source}" target="_blank" rel="noopener noreferrer">查阅本课官方资料 ↗</a></article></section><section class="editor-side" aria-label="练习区域"><div class="editor"><div class="editor-title"><span class="file-label"><i>${l.kind==='sql'?'SQL':guided?'↗':l.kind==='javascript'?'JS':l.kind==='typescript'?'TS':'PY'}</i>${esc(l.filename||(l.kind==='sql'?'practice.sql':guided?'本机实践参考':l.kind==='javascript'?'main.js':l.kind==='typescript'?'main.ts':'main.py'))}</span><button id="reset-code">恢复初始代码 ↺</button></div><div class="code-wrap"><div class="line-numbers" id="lines" aria-hidden="true">1</div><textarea id="code" class="code" aria-label="代码编辑区" spellcheck="false" autocapitalize="off" autocomplete="off"></textarea></div><div class="editor-actions"><small>${guided?'代码可复制到本机编辑器':'Ctrl / ⌘ + Enter 运行'}</small><div><button id="stop-run" class="runtime-stop" hidden>停止</button> <button id="run" class="primary">${guided?'复制练习代码':'▷ 运行并检查'}</button></div></div></div><div class="output-box"><div class="output-head"><span>${guided?'本机实践验收':'输出与检查'}</span><small id="runtime-label">${guided?'按步骤完成后自查':'等待运行'}</small></div><div id="output" class="output-content">${guided?'完成左侧步骤后，勾选下面的验收项，并回答知识问题。网页不会执行安装、Java 编译、大模型训练或启动本机服务。':'你的代码运行结果会显示在这里。\n准备好了，就点击上面的运行按钮。'}</div></div><p class="runtime-note">${guided?'本机实践的完成状态由你自查确认；知识测验由网页检查。':l.kind==='sql'?'真实 SQLite · 每次运行重建练习数据，不影响其他课程。':l.kind==='javascript'?'真实 JavaScript · 隔离运行，不访问网页 DOM 或本机文件。':l.kind==='typescript'?'TypeScript 5.9.3 · strict 类型检查后执行 JavaScript。':'真实 Python · 首次需联网加载；隔离环境不访问本站学习记录。'}</p>${guided?guidedQuiz(l):''}<div class="support-row"><button class="secondary" id="hint-button">☼ 给我一点提示</button><button class="secondary" id="solution-button">查看参考答案</button></div><div id="hint-area"></div><div class="note-box"><label for="note">✎ 用自己的话，记住这一步</label><textarea id="note" placeholder="今天我学会了…… / 我还不太理解……"></textarea></div></section></div><div class="lesson-bottom"><a class="secondary" href="#course/${track.id}">← 课程目录</a><span id="lesson-status">${state.done[l.id]?'✓ 本节已完成'+(guided?(l.conceptOnly?'（概念自查）':'（本机实践自查）'):''):'完成练习检查后，即可记入学习进度'}</span><button class="primary" id="next-lesson">${idx===lessons.length-1?'查看下一阶段 →':'下一小节 →'}</button></div>`;$('#code').value=state.drafts[l.id]??l.starter;$('#note').value=state.notes[l.id]||'';lines();$('#lesson-select').onchange=e=>go('#learn/'+e.target.value);$('#code').oninput=()=>{if(job){stopRun(false);setOutput('代码已修改，旧运行已取消。请重新检查当前版本。');}state.drafts[l.id]=$('#code').value;save();lines()};$('#code').onscroll=()=>{$('#lines').scrollTop=$('#code').scrollTop};$('#code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();let t=e.target,s=t.selectionStart;t.setRangeText('    ',s,t.selectionEnd,'end');t.dispatchEvent(new Event('input'))}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();runLesson()}};$('#note').oninput=e=>{state.notes[l.id]=e.target.value;save()};$('#reset-code').onclick=()=>{stopRun(false);setOutput('已恢复初始代码，请重新运行检查。');state.drafts[l.id]=l.starter;$('#code').value=l.starter;save();lines();toast('已恢复本节初始代码')};$('#run').onclick=runLesson;$('#stop-run').onclick=()=>stopRun(true);$('#hint-button').onclick=()=>{$('#hint-area').innerHTML=`<div class="hint-box"><b>一点提示</b><p>${l.hint}</p></div>`};$('#solution-button').onclick=()=>{state.viewedSolutions[l.id]=true;save();$('#hint-area').innerHTML=`<div class="hint-box"><b>参考答案 · 先理解，再自己写一次</b><pre>${esc(l.solution)}</pre><p class="muted">看懂答案不等于掌握。试着关掉它，重新完成练习。</p></div>`};$('#next-lesson').onclick=()=>{const next=lessons[idx+1];if(!state.done[l.id])toast('本节尚未完成，可以稍后回来继续。');go(next?'#learn/'+next.id:'#path')};if(guided){document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{state.checks[l.id]=[...document.querySelectorAll('[data-check]')].map(x=>x.checked);save()});$('#check-quiz').onclick=()=>checkQuiz(l)}}
function lines(){const t=$('#code');if(t)$('#lines').textContent=Array.from({length:t.value.split('\n').length},(_,i)=>i+1).join('\n')}
function guidedQuiz(l){return `<div class="note-box" style="margin:0 0 18px"><b style="font-size:14px">实践自查</b><div class="checklist">${(l.checks||[]).map((c,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[l.id]?.[i]?'checked':''}>${esc(c)}</label>`).join('')}</div><form id="quiz-form" class="quiz"><fieldset><legend>${esc(l.quiz.q)}</legend>${l.quiz.options.map((a,i)=>`<label class="option"><input type="radio" name="quiz" value="${i}">${esc(a)}</label>`).join('')}</fieldset><button class="primary" type="button" id="check-quiz">检查理解并记录完成</button></form></div>`}
function checkQuiz(l){const v=$('input[name=quiz]:checked');if(!v){toast('先选择一个答案');return}if(Number(v.value)!==l.quiz.answer){setOutput('再想一下：'+l.quiz.explanation,'error');return}if([...document.querySelectorAll('[data-check]')].some(e=>!e.checked)){setOutput(l.conceptOnly?'知识题答对了！请完成左侧小任务，再如实勾选自查项。':'知识题答对了！请先在本机完成实践，再如实勾选全部验收项。','');return}markDone(l);setOutput((l.conceptOnly?'✓ 知识检查通过；小任务由你自查确认。':'✓ 知识检查通过；本机实践由你自查确认。')+'\n'+l.quiz.explanation,'success')}
function setOutput(text,type=''){const o=$('#output');if(o){o.textContent=text;o.className='output-content '+type}}
function markDone(l){if(!state.done[l.id])state.done[l.id]=new Date().toISOString();save();if($('#lesson-status'))$('#lesson-status').textContent='✓ 本节已完成'+(l.kind==='guided'?(l.conceptOnly?'（概念自查）':'（本机实践自查）'):'');toast('完成一个小节，离目标又近了一步。每节首次完成 +20 XP。')}
async function runLesson(){const l=getLesson();if(l.kind==='guided'){try{await navigator.clipboard.writeText($('#code').value);toast('已复制，可粘贴到本机编辑器')}catch{toast('请选中编辑区代码后按 Ctrl+C 复制')}return}if(job)return;const code=$('#code').value;state.drafts[l.id]=code;save();$('#run').disabled=true;$('#stop-run').hidden=false;$('#runtime-label').textContent='正在运行';setOutput('正在准备 '+languageName(l.kind)+' 隔离执行器…\n首次运行可能需要联网，请稍候。');job={lesson:l};if(worker)worker.terminate();worker=new IsolatedRunner();{worker.onmessage=e=>{const m=e.data;if(m.type==='executing'){clearTimeout(timeout);timeout=setTimeout(()=>{stopRun(false);setOutput('执行超过 5 秒，已停止。检查循环退出条件。','error')},5000);return}if(m.type==='status'){if(job)setOutput(m.message);return}if(!job)return;const current=job.lesson;clearTimeout(timeout);worker?.terminate();worker=null;job=null;$('#run')&&($('#run').disabled=false);$('#stop-run')&&($('#stop-run').hidden=true);$('#runtime-label')&&($('#runtime-label').textContent=m.error?'需要修改':m.passed?'检查通过':'执行完成');setOutput((m.output||'（没有输出）')+'\n\n'+(m.error?'需要修改：'+m.error:m.passed?'✓ 练习检查通过'+(state.viewedSolutions[current.id]?' · 本节看过参考答案，建议独立重做。':''):'尚未通过：'+m.feedback),m.error||!m.passed?'error':'success');if(m.passed)markDone(current)};worker.onerror=()=>{setOutput('运行环境加载失败。请检查网络后重试；课程讲解和笔记仍可使用。','error');stopRun(false)}}worker.postMessage({kind:l.kind,code,test:l.test||'',setup:l.setup||'',expected:l.expected,verify:l.verify});timeout=setTimeout(()=>{stopRun(false);setOutput('运行超时，已停止。首次下载可能较慢，可稍后重试；如果写了循环，请检查退出条件。','error')},90000)}
function stopRun(show){clearTimeout(timeout);if(worker){worker.terminate();worker=null}job=null;if($('#run'))$('#run').disabled=false;if($('#stop-run'))$('#stop-run').hidden=true;if(show){setOutput('已停止运行。你可以修改代码后重新运行。');$('#runtime-label').textContent='已停止'}}
function renderPath(){crumb('学习路径');$('#main').innerHTML=`<div class="route-head"><div><span class="eyebrow">YOUR LEARNING JOURNEY</span><h1>从开关机开始，一小步一小步学</h1><p>${TRACKS.length} 个学习阶段 · ${LESSONS.length} 个实践小节 · ${PROJECTS.length} 个综合项目</p></div><span class="pill">前三阶段按顺序解锁</span></div><div class="journey-banner"><div><span class="eyebrow">下一步，只需要开始</span><h2>${esc(getLesson().title)}</h2><p>看一个动作，猜一次结果，亲手点一次，再用自己的话说一次。</p></div><a class="primary" href="#learn">继续我的学习 →</a></div><div class="track-grid">${TRACKS.map((t,i)=>{const ls=LESSONS.filter(l=>l.track===t.id),done=ls.filter(l=>state.done[l.id]).length,locked=!trackUnlocked(t.id),gate=trackGate(t.id);return `<article class="track-card ${locked?'locked':''}" style="--color:${t.color};--tint:${t.tint}"><div class="card-top"><span class="track-symbol">${locked?'🔒':esc(t.symbol)}</span><span class="eyebrow">阶段 ${String(i+1).padStart(2,'0')}</span></div><h2>${esc(t.name)}</h2><p>${esc(t.desc)}</p><p class="prereq">${locked?'解锁条件：完成 '+esc(gate.title):'先修：'+esc(t.prereq)}</p><div class="tiny-track"><i style="width:${done/ls.length*100}%"></i></div><div class="card-foot"><span>${done} / ${ls.length} 小节</span><a href="${locked?'#game/'+gate.id:'#course/'+t.id}">${locked?'去闯关解锁':done?'继续学习':'探索课程'} →</a></div></article>`}).join('')}</div><p class="muted" style="margin-top:25px">每节都按“看懂 → 预测 → 点击练习 → 小改动 → 独立做”展开。可以复练，不要求一次记住。</p>`}
function renderCourse(id){const t=TRACKS.find(x=>x.id===id);if(!t){go('#path');return}if(!trackUnlocked(id)){renderLockedTrack(id);return}crumb(t.name);const ls=LESSONS.filter(l=>l.track===id);$('#main').innerHTML=`<a class="back-link" href="#path">← 返回学习路径</a><div class="route-head"><div><span class="eyebrow">${esc(t.prereq)}</span><h1>${esc(t.name)}</h1><p>${esc(t.desc)}</p></div><span class="pill">${ls.length} 小节</span></div><div class="journey-banner"><div><span class="eyebrow">学完这一阶段，你将能够</span><h2>${esc(t.outcome)}</h2><p>跟着讲解练一次，再不看答案做一次。</p></div></div>${prerequisitePanel(id)}<div class="course-list">${ls.map((l,i)=>`<a class="course-row ${state.done[l.id]?'done':''}" href="#learn/${l.id}"><span class="number">${state.done[l.id]?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${l.kind==='guided'?(l.localLab?'本机实验 + 自查验收':'概念动手 + 知识检查'):l.kind==='sql'?'浏览器 SQL 实践':'浏览器 '+languageName(l.kind)+' 实践'}</p></div><span class="right">${l.minutes} 分钟 →</span></a>`).join('')}</div>`}
function renderProjects(){crumb('实战项目');$('#main').innerHTML=`<div class="route-head"><div><span class="eyebrow">BUILD SOMETHING REAL</span><h1>把知识，变成你的作品</h1><p>从小工具到 AI 应用。每个项目都有需求、步骤、参考实现和验收标准。</p></div></div><div class="project-grid">${PROJECTS.map((p,i)=>`<article class="project-card"><div class="project-label"><span>PROJECT ${String(i+1).padStart(2,'0')}</span><span>${esc(p.level)}</span></div><h2>${esc(p.title)}</h2><p>${esc(p.desc)}</p><div class="tags">${p.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><a class="primary" href="#project/${p.id}">进入项目 →</a></article>`).join('')}</div>`}
function renderProject(id){const p=PROJECTS.find(x=>x.id===id);if(!p){go('#projects');return}crumb(p.title);$('#main').innerHTML=`<div class="project-detail"><a class="back-link" href="#projects">← 返回实战项目</a><div class="route-head"><div><span class="eyebrow">${esc(p.level)} · ${esc(p.tags.join(' / '))}</span><h1>${esc(p.title)}</h1><p>${esc(p.desc)}</p></div><button class="secondary" id="download-project">下载项目指南 ↓</button></div><section class="project-stage"><h2>这次要交付什么</h2><p>${p.deliverable}</p><p><b>开始前：</b>${p.prereq}</p></section>${p.stages.map((s,i)=>`<section class="project-stage"><span class="eyebrow">STEP ${i+1}</span><h2>${s.title}</h2><ol>${s.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${s.code?`<details><summary>展开参考实现（先自己尝试）</summary><pre>${esc(s.code)}</pre></details>`:''}</section>`).join('')}<section class="project-stage"><h2>项目验收 · 在本机验证后勾选</h2><div class="checklist">${p.checks.map((x,i)=>`<label><input type="checkbox" data-project-check="${i}" ${state.projectChecks[p.id]?.[i]?'checked':''}>${esc(x)}</label>`).join('')}</div><p class="muted">这里记录你的自查结果，不代表网站已经运行或审查了本机项目。</p></section><section class="project-stage"><h2>独立挑战</h2><p>${p.challenge}</p><h3>复盘这三个问题</h3><p>数据从哪里来、到哪里去？最容易失败的是哪一步？如果需求改变，你会修改哪一部分？</p></section></div>`;document.querySelectorAll('[data-project-check]').forEach(e=>e.onchange=()=>{state.projectChecks[p.id]=[...document.querySelectorAll('[data-project-check]')].map(x=>x.checked);save()});$('#download-project').onclick=()=>download(p.id+'.md',projectMarkdown(p),'text/markdown')}
function projectMarkdown(p){const clean=s=>s.replace(/<[^>]*>/g,'');return '# '+p.title+'\n\n'+p.desc+'\n\n## 交付物\n'+clean(p.deliverable)+'\n\n先修：'+clean(p.prereq)+'\n\n'+p.stages.map((s,i)=>`## ${i+1}. ${s.title}\n\n${s.steps.map((x,j)=>`${j+1}. ${clean(x)}`).join('\n')}\n${s.code?'\n```\n'+s.code+'\n```\n':''}`).join('\n')+'\n## 验收\n'+p.checks.map(x=>'- [ ] '+x).join('\n')+'\n\n## 独立挑战\n'+clean(p.challenge)}
function renderNotes(){crumb('我的笔记');$('#main').innerHTML=`<div class="route-head"><div><span class="eyebrow">MAKE IT YOURS</span><h1>用自己的话，留下理解</h1><p>在课程右侧写下的笔记，会自动收集到这里。</p></div><input class="search-input" id="note-search" aria-label="搜索笔记" placeholder="搜索笔记或课程标题…"></div><div id="notes-list"></div>`;const draw=(q='')=>{const items=LESSONS.filter(l=>state.notes[l.id]?.trim()&&(l.title+state.notes[l.id]).toLowerCase().includes(q.toLowerCase()));$('#notes-list').innerHTML=items.length?items.map(l=>`<article class="note-card"><h2>${esc(l.title)}</h2><p>${esc(state.notes[l.id])}</p><a href="#learn/${l.id}">回到课程，继续编辑 →</a></article>`).join(''):`<div class="empty"><h2>${q?'没有找到匹配的笔记':'第一条笔记，从一个小发现开始'}</h2><p>${q?'换一个关键词试试。':'学完一课，用自己的话解释它，比抄下代码更有帮助。'}</p><a href="#learn" class="primary">回到学习工作台 →</a></div>`};draw();$('#note-search').oninput=e=>draw(e.target.value)}
function renderProgress(){crumb('学习记录');const done=LESSONS.filter(l=>state.done[l.id]);const pc=PROJECTS.filter(p=>p.checks.every((_,i)=>state.projectChecks[p.id]?.[i])).length;$('#main').innerHTML=`<div class="route-head"><div><span class="eyebrow">SMALL STEPS, REAL PROGRESS</span><h1>你走过的每一步，都算数</h1><p>实践小题和项目自查分别记录。掌握程度，需要独立解决问题来检验。</p></div></div><div class="stats-grid"><div class="stat"><b>${done.length}<small> / ${LESSONS.length}</small></b><span>已完成小节</span></div><div class="stat"><b>${Object.values(state.notes).filter(s=>s.trim()).length}</b><span>学习笔记</span></div><div class="stat"><b>${pc}<small> / ${PROJECTS.length}</small></b><span>已自查通过的项目</span></div></div><div class="history">${done.length?done.sort((a,b)=>state.done[b.id].localeCompare(state.done[a.id])).map(l=>`<a href="#learn/${l.id}" class="history-row"><span>✓ ${esc(l.title)}${l.kind==='guided'?' · 实践自查':''}${state.viewedSolutions[l.id]?' · 看过参考答案':''}</span><time>${new Date(state.done[l.id]).toLocaleDateString('zh-CN')}</time></a>`).join(''):'还没有完成记录。运行第一段代码，开始积累自己的进步。'}</div>`}
function download(name,body,type){exportTextFile(name,body,type)}
$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();$('#export-progress').onclick=()=>download('循码学习备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');$('#import-progress').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('文件过大');const s=JSON.parse(await f.text());if(s?.version!==1||!s.done||!s.notes||!s.drafts)throw Error('格式错误');state=LearningCore.merge(state,s,LESSONS,PROJECTS);save();render();toast('备份已合并；XP 按唯一完成记录计算，不重复累加')}catch{toast('导入失败：请选择有效的循码备份。')}e.target.value=''};window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){const lifetime=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'get_learning_progress',description:'读取当前浏览器内的课程完成记录，不修改进度。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({completed:LESSONS.filter(l=>state.done[l.id]).map(l=>l.id),total:LESSONS.length,current:state.current})},{signal:lifetime.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'open_lesson',description:'打开指定课程小节供学习，不标记完成。',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!LESSONS.some(l=>l.id===input.lessonId))throw Error('未知的小节');state.current=input.lessonId;save();history.replaceState(null,'','#learn/'+input.lessonId);render();return {opened:input.lessonId}}},{signal:lifetime.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifetime.abort(),{once:true})}catch{}}

